SELECT ?chiller ?name ?point ?pointtype WHERE {
  ?chiller a brick:Chiller .
  OPTIONAL { ?chiller rdfs:label ?name }
  OPTIONAL { ?point brick:isPOINTOf ?chiller . ?point a ?pointtype }
}

SELECT ?point ?ptype ?ts WHERE {
  ?point a ?ptype .
  ?point ref:hasTimeseriesId ?ts .
  FILTER(str(?point) LIKE "%Chiller01%Electric_Power%")
}

